/*
 * ls_fexit.c --- the C half of the function-exit trampoline: the shadow stack.
 *
 * The per-slot exit trampolines (ls_fexit_slot<n>, trampoline_x86_64.S) call:
 *
 *   ls_fexit_enter(slot, slot_addr, args)  at the hooked function's ENTRY ---
 *       record the real return address (and which exit-program slot to run) and
 *       hijack the stack slot.
 *   ls_fexit_leave(cur, retval)  when the body RETURNS into the stub --- find the
 *       matching frame (reclaiming any a non-local exit skipped), run the exit
 *       program, hand back the real return address.
 *
 * WHY KEYED BY THE STACK POINTER, not a plain LIFO. A skipped return (longjmp or
 * a C++ exception unwinding past a hooked frame) never runs that frame's `ret`,
 * so its exit stub never fires and its frame is never popped; a plain stack would
 * then pop a stale frame and return to the wrong address. Keying each frame to
 * the hijacked slot's address lets ls_fexit_leave discard every frame DEEPER than
 * the one returning (deeper == lower address; the stack grows down) before it
 * matches --- the reclaim kretprobes does. TMM itself has no longjmp and no C++
 * unwind (P8, on the build box), so this is a backstop; a future exit hook on an
 * unwind-traversable target is refused at arm time instead.
 *
 * ONE INSTANCE, no lock: TMM is core-pinned and run-to-completion, so two
 * invocations never overlap on a core --- the same assumption ls_vm.h makes. All
 * state is g_ls_fexit_*, which the TMM globals whitelist carries as a set.
 *
 * Status: mechanism proven by check_fexit.c (arms stand-ins; capture,
 * transparency, nesting, recursion, longjmp-reclaim). Running the exit PROGRAM
 * (ls_vm_call on struct ls_ctx_exit) is fexit step #2; today leave records.
 */

#include <stdint.h>
#include <string.h>

#include "ls_fexit.h"
#include "ls_vm.h"       /* ls_vm_call --- run the exit program on struct ls_ctx_exit */

/* Bounded: overflow degrades to "do not hijack" (a plain return), never grows or
 * crashes. 512 is far past any real depth under a single hooked chain. */
#define LS_FEXIT_DEPTH 512

struct ls_fexit_frame {
    uint64_t *slot;         /* address of the caller-return we overwrote (the key) */
    uint64_t  real_ret;     /* what was there --- where the function truly returns  */
    uint64_t  args[6];      /* rdi..r9 as captured at entry                         */
    uint64_t  seq;          /* which enter this was                                 */
    int       prog_slot;    /* which exit-program to run at leave                   */
};

/* Per-instance state. Non-static: the whole g_ls_fexit_* set is what the TMM
 * globals whitelist must declare, and the harness reads the counters/log. */
struct ls_fexit_frame g_ls_fexit_stack[LS_FEXIT_DEPTH];
int      g_ls_fexit_top;        /* number of live frames                            */
uint64_t g_ls_fexit_seq;        /* monotonic enter counter                          */

struct ls_fexit_event g_ls_fexit_log[LS_FEXIT_LOG];
unsigned g_ls_fexit_log_n;      /* exits recorded (capped at LS_FEXIT_LOG)          */
uint64_t g_ls_fexit_exits;      /* total exits observed                             */
uint64_t g_ls_fexit_reclaimed;  /* frames discarded as skipped (non-local exits)    */
uint64_t g_ls_fexit_overflow;   /* enters that could not hijack (depth exceeded)    */
uint64_t g_ls_fexit_desync;     /* leaves that found no matching frame (must be 0)  */

/* The exit STUB's address (trampoline_x86_64.S), written into the hijacked slot. */
extern char ls_fexit_stub[];

void
ls_fexit_reset(void)
{
    g_ls_fexit_top = 0;
    g_ls_fexit_seq = 0;
    g_ls_fexit_log_n = 0;
    g_ls_fexit_exits = g_ls_fexit_reclaimed = g_ls_fexit_overflow = g_ls_fexit_desync = 0;
    memset(g_ls_fexit_log, 0, sizeof g_ls_fexit_log);
}

/*
 * At the hooked function's entry. `slot` is the address of its caller-return on
 * the live stack; `args` points at the six saved integer-argument registers;
 * `prog_slot` is which exit program runs at leave.
 *
 * Record the frame, then overwrite *slot so the body returns into the stub. On
 * overflow we DO NOT hijack: the function returns normally, no exit fires, and
 * nothing is corrupted --- a bounded, safe degradation.
 */
void
ls_fexit_enter(int prog_slot, uint64_t *slot, const uint64_t *args)
{
    if (g_ls_fexit_top >= LS_FEXIT_DEPTH) {
        g_ls_fexit_overflow++;
        return;                                 /* do not hijack: plain return */
    }
    struct ls_fexit_frame *f = &g_ls_fexit_stack[g_ls_fexit_top++];
    f->slot      = slot;
    f->real_ret  = *slot;
    memcpy(f->args, args, sizeof f->args);
    f->seq       = ++g_ls_fexit_seq;
    f->prog_slot = prog_slot;

    *slot = (uint64_t)(void *)ls_fexit_stub;    /* the hijack */
}

/*
 * When the body returns into the stub. `cur` is rsp at stub entry --- exactly
 * (the hijacked slot's address) + 8, because the body's `ret` popped the slot.
 * So the returning frame has slot == cur - 8.
 *
 * Reclaim first: any frame whose slot is DEEPER (lower address) than the one
 * returning was skipped by a non-local exit --- discard it. Then the top frame
 * must be the match; pop it, run the exit program, return its real address.
 *
 * Fail-safe: if no frame matches (a desync we cannot resolve --- must not happen
 * for a hooked target under the arm-time rules), return `retval`.
 */
uint64_t
ls_fexit_leave(uint64_t cur, uint64_t retval)
{
    uint64_t *watermark = (uint64_t *)(cur - 8);

    while (g_ls_fexit_top > 0 && g_ls_fexit_stack[g_ls_fexit_top - 1].slot < watermark) {
        g_ls_fexit_top--;
        g_ls_fexit_reclaimed++;
    }

    if (g_ls_fexit_top == 0 || g_ls_fexit_stack[g_ls_fexit_top - 1].slot != watermark) {
        g_ls_fexit_desync++;
        return retval;                          /* unreachable under arm-time rules */
    }

    struct ls_fexit_frame *f = &g_ls_fexit_stack[--g_ls_fexit_top];

    /*
     * Run the exit program on the EXIT CONTEXT (fexit step #2): the entry
     * arguments plus the return value. arg[0..4] are rdi..r8, matching the entry
     * ctx; arg[5]/r9 is captured but not exposed (the entry ctx is five wide).
     *
     * The verdict is IGNORED --- the body has already run, so there is no
     * SAFE_RETURN to apply; an exit program is observe-only (read post-execution
     * state, stream, count). ls_vm_call fails open, exactly like the entry path:
     * a program that cannot run must not take TMM down with it.
     */
    struct ls_ctx_exit ctx = {0};
    ctx.arg[0] = f->args[0];
    ctx.arg[1] = f->args[1];
    ctx.arg[2] = f->args[2];
    ctx.arg[3] = f->args[3];
    ctx.arg[4] = f->args[4];
    ctx.ret    = retval;
    (void)ls_vm_call(f->prog_slot, &ctx, sizeof ctx);

    /* Record for `status` and the harness --- recent exits, like ls_vm.h's ctx
     * samples: a small per-instance ring, not the program's job. */
    g_ls_fexit_exits++;
    if (g_ls_fexit_log_n < LS_FEXIT_LOG) {
        struct ls_fexit_event *e = &g_ls_fexit_log[g_ls_fexit_log_n++];
        e->seq    = f->seq;
        e->slot   = f->prog_slot;
        e->retval = retval;
        memcpy(e->args, f->args, sizeof e->args);
    }

    return f->real_ret;
}

/*
 * ls_fexit.h --- the function-exit trampoline's shadow-stack interface.
 *
 * The per-slot exit trampolines (ls_fexit_slot<n>, in trampoline_x86_64.S) call
 * ls_fexit_enter / ls_fexit_leave; the harness (check_fexit.c) reads the log and
 * counters. See ls_fexit.c.
 *
 * All mutable state is a single per-instance block of g_ls_fexit_* globals ---
 * one VM per core-pinned run-to-completion TMM instance, so no lock, and the
 * whole set is what the TMM globals whitelist must carry (like g_ls_audit).
 */
#ifndef LS_FEXIT_H
#define LS_FEXIT_H

#include <stdint.h>
#include "ls_vm.h"

#define LS_FEXIT_LOG 64u        /* recent exits kept for inspection */

/* The exit payload retains arg[0..4] at bytes 0..39 and ret at bytes 40..47.
 * fexit/ selects the same 96-byte tracing descriptor as fentry/, so the rest
 * must also be allocated and zeroed before calling the program. */
struct ls_ctx_exit {
    uint64_t arg[5];            /* rdi..r8, as the entry ctx           */
    uint64_t ret;              /* the hooked function's return value  */
    uint64_t reserved[LS_TRACING_CTX_SIZE / sizeof(uint64_t) - 6];
};
_Static_assert(sizeof(struct ls_ctx_exit) == LS_TRACING_CTX_SIZE,
               "exit context must cover the verifier's tracing region");
_Static_assert(offsetof(struct ls_ctx_exit, ret) == 40,
               "exit return-value offset must not change");
_Static_assert(offsetof(struct ls_ctx_exit, reserved) == 48,
               "exit payload must remain 48 bytes");

/* One observed exit: what the exit program would have been handed, plus which
 * slot's program it was. */
struct ls_fexit_event {
    uint64_t seq;               /* which enter this paired with           */
    int      slot;              /* which exit-program slot                */
    uint64_t retval;            /* the hooked function's return value      */
    uint64_t args[6];           /* rdi..r9 captured at entry               */
};

/* Called from the per-slot exit trampoline. `slot` is which exit-program to run
 * at leave; `slot_addr` is the caller-return to hijack; `args` the saved rdi..r9. */
void     ls_fexit_enter(int slot, uint64_t *slot_addr, const uint64_t *args);
uint64_t ls_fexit_leave(uint64_t cur, uint64_t retval);

/* Clear all state between test cases (and at instance init). */
void ls_fexit_reset(void);

/* Per-instance state / observability (defined in ls_fexit.c). */
extern struct ls_fexit_event g_ls_fexit_log[LS_FEXIT_LOG];
extern unsigned g_ls_fexit_log_n;
extern uint64_t g_ls_fexit_exits;
extern uint64_t g_ls_fexit_reclaimed;
extern uint64_t g_ls_fexit_overflow;
extern uint64_t g_ls_fexit_desync;

#endif /* LS_FEXIT_H */

/*
 * ls_tramp.c --- the C half of the patched-entry trampoline.
 *
 * The assembly in trampoline_x86_64.S is generic: it saves the ABI's argument
 * registers, calls this, and acts on the verdict. Everything PER-HOOK lives
 * here, in C, because the ctx layout is generated from the build's DWARF
 * (development-scope.md item 6) and changes whenever a hooked function's
 * signature does. Putting it in assembly would mean regenerating assembly per
 * hook, which is the cost this split exists to avoid.
 *
 * Status: LIVE. ls_tramp_dispatch is reached from a patched function entry on every
 * armed hook, on a running TMM under traffic. This comment read "candidate artifact...
 * Nothing calls it" until 2026-08-18 --- true before arming was built, and the opposite
 * of true since.
 */

#include "ls_vm.h"
#include "ls_arm.h"

/* Slot numbers live in ls_slots.h, checked for collisions by the compiler. They
 * were here as a bare macro whose value (0, the shield slot) contradicted the
 * comment above it (7) --- so slot 0 got the parse ctx instead of the generic
 * register ctx. See ls_slots.h. */

#include <stdint.h>
#include <string.h>

/* What the assembly expects back. rax carries this; rdx carries the safe value
 * when it is 1. Kept as plain ints because the asm reads eax. */
#define LS_TRAMP_FALLTHROUGH 0
#define LS_TRAMP_SAFE_RETURN 1

/*
 * Called with the hooked function's first five integer arguments, exactly as
 * the ABI delivered them, before its prologue ran.
 *
 * The returned safe_value is what the hooked function's caller should see if we
 * skip the body; the assembly moves it to rax. What counts as safe is per-hook
 * and belongs to the safe-return policy table (item 7); a slot carries its own.
 *
 * Returns LS_TRAMP_SAFE_RETURN to skip the hooked function entirely.
 */
/*
 * Returned in rax:rdx by the System V ABI --- which is precisely the pair the
 * assembly reads. An earlier draft took a seventh `uint64_t *safe_out`
 * argument; the ABI puts a seventh argument on the STACK, while the call site
 * passes only six registers, so the callee would have dereferenced whatever
 * happened to be at that address. Returning the pair removes the mismatch by
 * construction rather than by both sides remembering the same convention.
 */
/* struct ls_tramp_result lives in ls_arm.h */

struct ls_tramp_result
ls_tramp_dispatch(int slot, const struct ls_regs *regs)
{
    struct ls_tramp_result r = { LS_TRAMP_FALLTHROUGH, 0 };

    /*
     * ALL SIX arguments, via a pointer to the block the trampoline already saved
     * (Phase 3). The named accessors in ls_arm.h exist because the block is in
     * STACK order, which is the reverse of ABI order --- indexing it by argument
     * position would silently swap arguments rather than fail.
     *
     * regs is NULL only if something other than the trampoline called this. Guard
     * rather than trust: a fall-through is always a safe answer.
     */
    uint64_t a0, a1, a2, a3, a4;

    if (regs == 0)
        return r;

    a0 = LS_ARG0(regs);
    a1 = LS_ARG1(regs);
    a2 = LS_ARG2(regs);
    a3 = LS_ARG3(regs);
    a4 = LS_ARG4(regs);
    /*
     * The ctx is a per-invocation stack copy, never a view onto the argument
     * registers or onto TMM state. PREVAIL cannot express a read-only region,
     * so a verified program can write every byte of what it is handed
     * (finding O1); handing it the live frame would make the safety mechanism
     * an argument-injection primitive.
     *
     * PREVAIL's tracing descriptor permits 96 bytes, even though the argument
     * payload is only 40. Allocate and initialise the entire verified region;
     * otherwise a verified JIT load/store can reach this function's own frame.
     * The reserved tail is reset on EVERY invocation, including after a program
     * writes it. Existing programs retain their five argument offsets.
     */
    struct ls_ctx_generic ctx = {0};

    ctx.arg[0] = a0;
    ctx.arg[1] = a1;
    ctx.arg[2] = a2;
    ctx.arg[3] = a3;
    ctx.arg[4] = a4;

    /*
     * ONE PATH: the generic five-register context. There are no typed, per-hook ctx builders
     * any more. A program reads whatever fields it needs from the argument pointers via CO-RE
     * relocations resolved against the target build's BTF before signing, so the host
     * never learns any hook's layout --- which is what removed the "burns a build per data
     * source" coupling: adding a data source is writing bytecode now, not editing TMM. An
     * arbitrary armed function therefore gets exactly this: the register block, nothing
     * dereferenced.
     */
    if (ls_vm_call(slot, &ctx, sizeof ctx) != LS_SAFE_RETURN)
        return r;

    /*
     * The safe value belongs to the SLOT (item 7). v1 carries one configured
     * value per slot (ls_vm_safe_value, set from LS_SHIELD_SAFE_VALUE at arm) ---
     * not yet the full per-return-type policy table, but enough that an err_t
     * hook returns ERR_BUF instead of 0. Zero was right for a pointer/BOOL hook
     * and wrong for one whose caller treats 0 as success, which converts a crash
     * into silent misbehaviour: dtls_tx is precisely that case (0 == ERR_OK).
     */
    r.verdict    = LS_TRAMP_SAFE_RETURN;
    r.safe_value = ls_vm_safe_value(slot);
    return r;
}

/*
 * ls_vm.h --- the embedded eBPF VM, as TMM would see it.
 *
 * This is the smallest interface that makes "TMM has its own BPF VM" a true
 * statement: a VM instance owned by TMM, created at startup, holding verified
 * programs, callable from a TMM code path, with its result acted on.
 *
 * Four calls. Everything else in development-scope.md --- the trampoline, pad
 * rewriting, the safe point, the signing chain --- exists to hook functions
 * NOBODY PLANNED FOR. None of it is needed to embed the VM itself, which is why
 * this is the first increment rather than the last.
 *
 * Shape follows TMM's, and the reasons matter:
 *
 *   - ONE VM PER TMM INSTANCE, never shared. TMM is core-pinned and
 *     run-to-completion, so a per-instance VM needs no lock on the call path.
 *     A shared VM would need one, and a lock in the poll loop is the thing this
 *     design cannot afford.
 *   - INTERPRETER, not the native-code path, for the first cut. uBPF's
 *     instruction limit "has no effect on JIT'd programs" (ubpf.h) but does work
 *     in the interpreter, and the native path's prologue opens a 4KB frame with
 *     no guard-page probe at arbitrary call depth (findings O6, O7). Switching
 *     later is one call, once those are addressed.
 *   - THE CTX IS A COPY. PREVAIL cannot express a read-only region, so a verified
 *     program can write every byte of what it is handed (finding O1). Handing it
 *     a live view of TMM state would make the safety mechanism deliver a
 *     state-injection primitive. The caller fills a per-instance scratch struct.
 *
 * Status: candidate artifact. It compiles against the real uBPF headers. It is
 * not wired into TMM here --- see ls_vm.c for exactly which lines would be the
 * TMM-side change.
 */

#ifndef LS_VM_H
#define LS_VM_H

#include <stdbool.h>
#include <stddef.h>   /* size_t --- this header must stand alone */
#include <stdint.h>

/* PREVAIL's tracing descriptor (fentry/ and fexit/) permits 96 context bytes.
 * The JIT does not bounds-check these accesses: every trampoline must supply
 * the full allocation, with a zeroed tail, not just the fields a program uses.
 * Keep this in step with the pinned verifier; CONTESTED-PREMISES.md §17.
 */
#define LS_TRACING_CTX_SIZE 96u

struct ls_ctx_generic {
    uint64_t arg[5];
    uint64_t reserved[LS_TRACING_CTX_SIZE / sizeof(uint64_t) - 5];
};
_Static_assert(sizeof(struct ls_ctx_generic) == LS_TRACING_CTX_SIZE,
               "entry context must cover the verifier's tracing region");
_Static_assert(offsetof(struct ls_ctx_generic, reserved) == 40,
               "entry argument offsets must not change");

/* Outcomes the host owns. The program SELECTS one; the host APPLIES it. In
 * observe mode the host counts the selection and applies nothing --- observe is
 * not a seventh outcome (substrate §2). */
enum ls_verdict {
    LS_FALLTHROUGH = 0,   /* run the original function body                */
    LS_SAFE_RETURN = 1,   /* skip the body, return the declared safe value */
};

enum ls_mode {
    LS_MODE_DISABLE = 0,
    LS_MODE_MONITOR = 1,  /* evaluate and count; do not apply */
    LS_MODE_ENFORCE = 2,
};

/* The last few ctx values the hook was called with.
 *
 * Move-4 instrument: when the hook starts firing, `fired > 0` with
 * `safe_returns == 0` is ambiguous --- the shield may be wrong, or the CVE
 * condition may simply never have arrived. Without a sample there is no way to
 * tell those apart, and they call for opposite responses.
 *
 * Deliberately tiny and fixed: 8 entries of 32 bytes, in the slot, overwritten
 * oldest-first. This is development-scope.md item 14's ring at a scale that
 * needs no allocator, no drain agent and no backpressure policy --- the real one
 * is per-core shared memory with a consumer ABI. Sized to answer one question,
 * not to be that. */
#define LS_CTX_SAMPLES 8
#define LS_CTX_SAMPLE_BYTES 48   /* fits the fexit payload (arg[5] + ret = 48B), so a
                                  * sample captures the RETURN VALUE at offset 40, not
                                  * just the first four args. Was 32 (entry ctx only). */

struct ls_ctx_sample {
    uint64_t seq;                              /* which invocation this was  */
    uint32_t len;                              /* the ctx's real length      */
    uint32_t verdict;
    uint8_t  bytes[LS_CTX_SAMPLE_BYTES];       /* truncated, deliberately    */
};

/* One armed program. TMM holds a small fixed array of these per instance ---
 * fixed because allocating on the call path is not acceptable. */

struct ls_slot {
    void        *vm;        /* struct ubpf_vm *, opaque here          */
    void        *jit_fn;    /* ubpf_jit_fn when JIT'd; NULL = interpret.
                             * Held separately because ubpf_exec never
                             * dispatches to compiled code --- the pointer IS
                             * the only route to it. */
    enum ls_mode mode;
    bool         armed;
    bool         is_exit;       /* fexit hook: arm via ls_fexit_table, not the
                                 * entry table. Set at load from the program's
                                 * fexit/ vs fentry/ section; read at arm. */
    uint64_t     safe_value;    /* what the CALLER receives when SAFE_RETURN skips
                                 * the body (item 7). ZERO IS NOT UNIVERSALLY SAFE:
                                 * for an err_t-returning hook 0 is ERR_OK ---
                                 * "succeeded" --- so a shield that skips dtls_tx
                                 * must return ERR_BUF(2), not 0, or it converts a
                                 * crash into silent misbehaviour. Set per arm
                                 * (LS_SHIELD_SAFE_VALUE); delivered by
                                 * ls_tramp_dispatch. */
    uint64_t     fired;         /* per-instance; a box-wide sum is wrong */
    uint64_t     safe_returns;
    uint64_t     errors;        /* exec faults: fuel exhausted, bounds  */
    uint64_t     cycles;        /* only when timing is enabled          */
    uint64_t     cycles_max;    /* the tail is what bounds a hot hook   */
    uint64_t     cycles_min;    /* the floor: least preemption-polluted */
    uint32_t     gen;           /* bumped per reload. Counters above are
                                 * per SLOT and SURVIVE a program swap ---
                                 * on 2026-08-17 a safe_returns=246 left by
                                 * one program was twice read as evidence
                                 * about the next. `gen` lets a reader tell
                                 * residue from result. */
    struct ls_ctx_sample samples[LS_CTX_SAMPLES];
    uint32_t     sample_next;
};

/* A snapshot of one slot, for whatever eventually reports these. Copied rather
 * than returning a pointer, because the caller must not be able to reach into
 * live VM state. The permanent home for these numbers is `tmstat`, TMM's own
 * statistics mechanism, which is already linked into the runtime image ---
 * see development-scope.md item 14. Until then, logging. */
struct ls_stats {
    bool     armed;
    bool     is_exit;        /* fexit hook (armed via ls_fexit_table) */
    int      mode;
    uint64_t fired;
    uint64_t safe_returns;
    uint32_t gen;            /* increments per reload --- see ls_vm_stats */
    uint64_t errors;
    uint64_t cycles;
    uint64_t cycles_max;
    uint64_t cycles_min;
};

/* The form TMM actually calls. Applies the environment overrides --- program
 * source, section, function, mode --- over the compiled-in defaults, so the
 * call site never has to know they exist. Pass the built-in blob and its two
 * identities; LS_SHIELD_PATH replaces the blob, LS_SHIELD_SECTION and
 * LS_SHIELD_FUNCTION replace the names, LS_SHIELD_MODE replaces the mode.
 *
 * This is what makes a shield change a pod restart rather than a rebuild. */
int ls_vm_arm_configured(const void *blob, size_t blob_len,
                         const char *section, const char *function);

/* Off the data path. Returns false for an out-of-range slot. */
/* The single STT_FUNC symbol defined in `section` of `elf`, copied into out[outlen].
 * Returns its length, or 0 if none/ambiguous. Lets the loader take a program's entry
 * function FROM the object it verified, instead of assuming a fixed name. */
size_t ls_function_in_section(const void *elf, size_t elf_len, const char *section,
                              char *out, size_t outlen);

bool ls_vm_stats(int slot, struct ls_stats *out);

/* The value the trampoline hands the hooked function's caller on SAFE_RETURN for
 * this slot (item 7). Off the data path only in that it is read once per skipped
 * call; returns 0 for an out-of-range or unarmed slot, which is the fail-safe for
 * a pointer/BOOL return and the documented wrong answer for an err_t one --- which
 * is why it is configurable. */
uint64_t ls_vm_safe_value(int slot);

/* Copy out the recent ctx samples. Off the data path. Returns how many were
 * written, up to LS_CTX_SAMPLES. */
unsigned ls_vm_samples(int slot, struct ls_ctx_sample *out, unsigned max);

/* Benchmark an ARBITRARY program without arming it onto a hook --- move-3
 * instrument. Loading a program, benching it and discarding it is what turns
 * budget-pass calibration from one restart per data point into one message per
 * data point. Returns 0 on success and fills min/mean/max.
 *
 * QUOTE THE MIN. The mean is 2-3x it and swings run to run --- 194 to 538 for one program on
 * an idle box --- because a single rdtsc pair spanning a context switch dominates the total.
 * That is the same effect that makes the armed-hook counter mean unusable, and it is why the
 * max is reported: seeing 130,720 next to a min of 132 is what tells a reader the mean is
 * measuring the scheduler.
 *
 * `jitted_out` says WHICH EXECUTION PATH was measured, and it is not optional information.
 * This function used to time the interpreter unconditionally while every armed hook runs
 * jit_fn, so the figure described a path nothing uses. It now compiles when the configuration
 * does, falls back to the interpreter if the JIT fails, and reports which happened --- a
 * caller that ignores this can publish an interpreter number as a hook cost, which is the
 * mistake the flag exists to prevent. Pass NULL only if you genuinely do not care.
 *
 * IT IS STILL A FLOOR, not the cost of an armed hook. It measures program execution in a
 * tight loop with a warm cache and no contention. A live hook additionally pays the
 * trampoline's register save and restore, the call and return, and cache effects from real
 * traffic. */
int ls_vm_bench_program(const void *elf, size_t elf_len,
                        const char *section, const char *function,
                        uint32_t iters,
                        uint64_t *min_out, uint64_t *mean_out, uint64_t *max_out,
                        int *jitted_out);

/* Whether signature enforcement is on --- see ls_vm_config.c for why the opt-out is a word
 * rather than a boolean. Exported so the loader does not become a second reader of the
 * environment; the one thing two config readers must never disagree about is whether a
 * security gate is armed. */
int ls_vm_sig_enforce(void);

/* Log the current counters for every armed slot. Called at fini, every
 * LS_VM_REPORT_EVERY invocations, and on demand. */
void ls_vm_report(void);

/* Create this instance's VM state. Called once per TMM instance at startup,
 * off the data path. Returns false and leaves nothing armed on any failure ---
 * a TMM that cannot bring up the VM must run exactly as it does today. */
bool ls_vm_init(void);

/* Load a VERIFIED, SIGNED program object into a slot and arm it. Off the data
 * path (admission time). Signature checking happens BEFORE this.
 *
 * BOTH names are required, and that is not redundancy --- the verifier and the
 * runtime identify a program differently:
 *
 *   PREVAIL  selects by ELF SECTION name   ("fentry/<hook>")
 *   uBPF     selects by FUNCTION SYMBOL    ("shield")   [ubpf_loader.c:271,
 *            despite its header calling the parameter `main_section_name`]
 *
 * So "PREVAIL verified this object" and "uBPF is about to run this program" are
 * statements about two different identities, and in an object carrying several
 * functions they can denote different code. This function refuses unless the
 * named symbol actually lives in the named section --- see finding O14. Passing
 * one name and hoping is how a verified-but-not-the-verified-one program loads.
 *
 * Returns the slot index, or -1. */
int ls_vm_arm(const void *elf, size_t elf_len,
              const char *section, const char *function, enum ls_mode m);

/* THE CALL PATH. Everything above is setup; this is the part that runs per
 * invocation and the only part whose cost is in the poll loop.
 *
 * ctx points at the caller's scratch copy of the fields the program needs.
 * Returns the verdict the host must apply, or LS_FALLTHROUGH on any error ---
 * fail-open is correct HERE and only here: a shield that cannot run must not
 * take TMM down with it. Admission fails closed; invocation fails open. */
enum ls_verdict ls_vm_call(int slot, void *ctx, size_t ctx_len);

/* Runtime load path (ls_vm_load.c). Started only if LS_LOAD_SOCKET is set.
 * VERIFIES EVERY PROGRAM'S SIGNATURE (ls_sig.c) and NOTHING ABOUT ITS SENDER: the
 * socket has no peer authentication, so the env gate and the 0600 mode are what
 * limit who may ask. Off by default for that reason --- which is a different reason
 * from the one this comment carried until 2026-08-20. */
void ls_vm_loader_start(void);

int  ls_vm_reload(int slot, const void *elf, size_t elf_len,
                  const char *section, const char *function, enum ls_mode m);
void ls_vm_set_mode(int slot, enum ls_mode m);

void ls_vm_fini(void);

#endif /* LS_VM_H */

